@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(threadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    SelectedChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@currentChannelName"
                 ChannelDescription="@currentChannelDescription"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoadingMore="isLoadingMore"
                 OnThreadOpen="OpenThread"
                 OnSendMessage="SendMessage"
                 OnReact="HandleReaction"
                 OnLoadMore="LoadMoreMessages" />

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private int selectedChannelId;
    private string currentChannelName = "";
    private string currentChannelDescription = "";

    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    private bool isLoadingMore;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        var channel = channels.First(c => c.Id == channelId);
        currentChannelName = channel.Name;
        currentChannelDescription = channel.Description;

        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        threadSummaries = BuildThreadSummaries(messages);
        threadOpen = false;

        await ChatService.MarkChannelReadAsync(channelId);

        // Update local unread count
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channel with { UnreadCount = 0 };
        }
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(message);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update local state
        var msg = messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
        }
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update thread summary
        var existing = threadSummaries.FirstOrDefault(t => t.RootMessageId == threadRootMessage.Id);
        if (existing is not null)
        {
            threadSummaries.Remove(existing);
        }
        threadSummaries.Add(new ThreadSummary(threadRootMessage.Id, threadReplies.Count, DateTime.UtcNow));
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            threadSummaries = BuildThreadSummaries(messages);
        }

        isLoadingMore = false;
    }

    private static List<ThreadSummary> BuildThreadSummaries(List<Message> msgs)
    {
        // Group replies by their root message to build thread summaries
        var replies = msgs.Where(m => m.ReplyToId.HasValue).ToList();
        return replies
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

.sidebar-header {
    padding: 16px;
    font-size: 1rem;
    font-weight: 700;
    border-bottom: 1px solid #202225;
    margin: 0;
}

.channel-list {
    list-style: none;
    padding: 8px 0;
    margin: 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 2px 8px;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px;
    position: relative;
}

.channel-item:hover {
    background: #36393f;
}

.channel-item.active {
    background: #42464d;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
    flex: 1;
}

.channel-description {
    font-size: 0.75rem;
    color: #8e9297;
    width: 100%;
}

.unread-badge {
    background: #ed4245;
    color: #fff;
    border-radius: 10px;
    padding: 1px 6px;
    font-size: 0.7rem;
    font-weight: 700;
}

/* Message Area */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
    min-width: 0;
}

.message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.channel-desc {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #8e9297;
    font-size: 0.8rem;
}

.message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
}

.message-bubble:hover {
    background: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.7rem;
    color: #72767d;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    word-break: break-word;
}

.message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 4px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dcddde;
}

.reaction-badge:hover {
    border-color: #dcddde;
}

.thread-link {
    background: none;
    border: none;
    color: #00aff4;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 4px;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    display: flex;
    gap: 2px;
    padding: 2px;
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 3px;
    font-size: 0.9rem;
}

.action-btn:hover {
    background: #4f545c;
}

.emoji-picker {
    position: absolute;
    top: -40px;
    right: 8px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    display: flex;
    gap: 2px;
    padding: 4px;
    z-index: 10;
}

.emoji-option {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.2rem;
    padding: 4px;
    border-radius: 3px;
}

.emoji-option:hover {
    background: #4f545c;
}

/* Message Input */
.message-input-area,
.thread-input-area {
    padding: 12px 16px;
    border-top: 1px solid #202225;
    display: flex;
    gap: 8px;
    flex-shrink: 0;
}

.message-input,
.thread-input {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 8px;
    padding: 10px 12px;
    color: #dcddde;
    font-size: 0.9rem;
    resize: none;
    min-height: 40px;
    max-height: 120px;
    font-family: inherit;
}

.message-input:focus,
.thread-input:focus {
    outline: none;
}

.send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 8px 16px;
    font-weight: 600;
    cursor: pointer;
    align-self: flex-end;
}

.send-btn:hover {
    background: #4752c4;
}

.send-btn:disabled {
    background: #4f545c;
    cursor: not-allowed;
}

/* Thread Panel */
.thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2f3136;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #202225;
}

.thread-header {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

.close-btn {
    background: none;
    border: none;
    color: #8e9297;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #4f545c;
    color: #fff;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
    flex-shrink: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.thread-reply {
    padding: 8px;
    border-radius: 4px;
}

.thread-reply:hover {
    background: #36393f;
}

/* Layout adjustments when thread is open */
.chat-layout.thread-open .message-area {
    width: 55%;
}

