+.message-area-header h2 {
+    margin: 0;
+    font-size: 1.1rem;
+    color: #fff;
+}
+
+.channel-desc {
+    margin: 4px 0 0;
+    font-size: 0.8rem;
+    color: #8e9297;
+}
+
+.message-list {
+    flex: 1;
+    overflow-y: auto;
+    padding: 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 4px;
+}
+
+.loading-indicator {
+    text-align: center;
+    padding: 8px;
+    color: #8e9297;
+    font-size: 0.8rem;
+}
+
+.message-bubble {
+    padding: 8px 12px;
+    border-radius: 4px;
+    position: relative;
+}
+
+.message-bubble:hover {
+    background: #32353b;
+}
+
+.message-header {
+    display: flex;
+    align-items: baseline;
+    gap: 8px;
+    margin-bottom: 2px;
+}
+
+.message-author {
+    font-weight: 600;
+    color: #fff;
+    font-size: 0.9rem;
+}
+
+.message-time {
+    font-size: 0.7rem;
+    color: #72767d;
+}
+
+.message-content {
+    font-size: 0.9rem;
+    line-height: 1.4;
+    word-break: break-word;
+}
+
+.message-reactions {
+    display: flex;
+    gap: 4px;
+    margin-top: 4px;
+    flex-wrap: wrap;
+}
+
+.reaction-badge {
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    padding: 2px 6px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    color: #dcddde;
+}
+
+.reaction-badge:hover {
+    border-color: #dcddde;
+}
+
+.thread-link {
+    background: none;
+    border: none;
+    color: #00aff4;
+    font-size: 0.8rem;
+    cursor: pointer;
+    padding: 4px 0;
+    margin-top: 4px;
+}
+
+.thread-link:hover {
+    text-decoration: underline;
+}
+
+.message-actions {
+    position: absolute;
+    top: -8px;
+    right: 8px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    display: flex;
+    gap: 2px;
+    padding: 2px;
+}
+
+.action-btn {
+    background: none;
+    border: none;
+    cursor: pointer;
+    padding: 4px 6px;
+    border-radius: 3px;
+    font-size: 0.9rem;
+}
+
+.action-btn:hover {
+    background: #4f545c;
+}
+
+.emoji-picker {
+    position: absolute;
+    top: -40px;
+    right: 8px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    display: flex;
+    gap: 2px;
+    padding: 4px;
+    z-index: 10;
+}
+
+.emoji-option {
+    background: none;
+    border: none;
+    cursor: pointer;
+    font-size: 1.2rem;
+    padding: 4px;
+    border-radius: 3px;
+}
+
+.emoji-option:hover {
+    background: #4f545c;
+}
+
+/* Message Input */
+.message-input-area,
+.thread-input-area {
+    padding: 12px 16px;
+    border-top: 1px solid #202225;
+    display: flex;
+    gap: 8px;
+    flex-shrink: 0;
+}
+
+.message-input,
+.thread-input {
+    flex: 1;
+    background: #40444b;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 12px;
+    color: #dcddde;
+    font-size: 0.9rem;
+    resize: none;
+    min-height: 40px;
+    max-height: 120px;
+    font-family: inherit;
+}
+
+.message-input:focus,
+.thread-input:focus {
+    outline: none;
+}
+
+.send-btn {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 8px;
+    padding: 8px 16px;
+    font-weight: 600;
+    cursor: pointer;
+    align-self: flex-end;
+}
+
+.send-btn:hover {
+    background: #4752c4;
+}
+
+.send-btn:disabled {
+    background: #4f545c;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2f3136;
+    color: #dcddde;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #202225;
+}
+
+.thread-header {
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    flex-shrink: 0;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    color: #8e9297;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #4f545c;
+    color: #fff;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+    background: #36393f;
+    flex-shrink: 0;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 8px;
+}
+
+.thread-reply {
+    padding: 8px;
+    border-radius: 4px;
+}
+
+.thread-reply:hover {
+    background: #36393f;
+}
+
+/* Layout adjustments when thread is open */
+.chat-layout.thread-open .message-area {
+    width: 55%;
+}
+

